INSERT INTO literary_references (id, domain_id, source_id, title, creator, reference_text, analysis_text, source_reference, source_text, sheet_name, source_row, position) VALUES ('literature-feuil1-r02', 'references', 'references-litteraires', 'Le Petit Prince', 'Antoine de Saint-Exupéry', 'On peut également penser au Petit Prince d’Antoine de Saint-Exupéry, dans lequel le personnage principal voyage de planète en planète et découvre différentes façons de penser et de vivre.', 'Cette référence montre que la découverte de l’autre peut conduire à mieux comprendre le monde mais aussi à mieux se comprendre soi-même.', 'Le Petit Prince – Saint-Exupéry', 'On peut également penser au Petit Prince d’Antoine de Saint-Exupéry, dans lequel le personnage principal voyage de planète en planète et découvre différentes façons de penser et de vivre. Cette référence montre que la découverte de l’autre peut conduire à mieux comprendre le monde mais aussi à mieux se comprendre soi-même.', 'Feuil1', 2, 1);
