INSERT INTO literary_references (id, domain_id, source_id, title, creator, reference_text, analysis_text, source_reference, source_text, sheet_name, source_row, position) VALUES ('literature-feuil1-r03', 'references', 'references-litteraires', 'Candide', 'Voltaire', 'On peut également penser à Candide de Voltaire, dans lequel le héros traverse de nombreux pays et affronte des situations qui remettent progressivement en cause ses certitudes.', 'Cette référence montre que les expériences vécues peuvent transformer notre manière de penser et nous conduire à porter un regard plus critique sur le monde.', 'Candide – Voltaire', 'On peut également penser à Candide de Voltaire, dans lequel le héros traverse de nombreux pays et affronte des situations qui remettent progressivement en cause ses certitudes. Cette référence montre que les expériences vécues peuvent transformer notre manière de penser et nous conduire à porter un regard plus critique sur le monde.', 'Feuil1', 3, 2);
