INSERT INTO literary_references (id, domain_id, source_id, title, creator, reference_text, analysis_text, source_reference, source_text, sheet_name, source_row, position) VALUES ('literature-feuil1-r04', 'references', 'references-litteraires', 'L’Odyssée', 'Homère', 'On peut également penser à L’Odyssée d’Homère, dans laquelle Ulysse affronte de nombreuses épreuves avant de retrouver son foyer.', 'Cette référence montre que les difficultés rencontrées au cours d’un parcours peuvent mettre à l’épreuve un individu, mais aussi renforcer sa détermination et son identité.', 'L’Odyssée – Homère', 'On peut également penser à L’Odyssée d’Homère, dans laquelle Ulysse affronte de nombreuses épreuves avant de retrouver son foyer. Cette référence montre que les difficultés rencontrées au cours d’un parcours peuvent mettre à l’épreuve un individu, mais aussi renforcer sa détermination et son identité.', 'Feuil1', 4, 3);
