INSERT INTO literary_references (id, domain_id, source_id, title, creator, reference_text, analysis_text, source_reference, source_text, sheet_name, source_row, position) VALUES ('literature-feuil1-r05', 'references', 'references-litteraires', 'Les Misérables', 'Victor Hugo', 'On peut également penser aux Misérables de Victor Hugo, dans lesquels Jean Valjean parvient progressivement à transformer son existence grâce aux rencontres et aux choix qu’il effectue.', 'Cette référence montre qu’un individu n’est pas nécessairement prisonnier de son passé et qu’il peut évoluer au contact des autres.', 'Les Misérables – Victor Hugo', 'On peut également penser aux Misérables de Victor Hugo, dans lesquels Jean Valjean parvient progressivement à transformer son existence grâce aux rencontres et aux choix qu’il effectue. Cette référence montre qu’un individu n’est pas nécessairement prisonnier de son passé et qu’il peut évoluer au contact des autres.', 'Feuil1', 5, 4);
