INSERT INTO literary_references (id, domain_id, source_id, title, creator, reference_text, analysis_text, source_reference, source_text, sheet_name, source_row, position) VALUES ('literature-feuil1-r06', 'references', 'references-litteraires', 'Le Journal d’Anne Frank', 'Anne Frank', 'On peut également penser au Journal d’Anne Frank, dans lequel une adolescente met par écrit ses pensées, ses émotions et son quotidien alors qu’elle vit cachée pendant la Seconde Guerre mondiale.', 'Cette référence montre que l’écriture peut aider à exprimer son vécu tout en laissant un témoignage destiné aux générations futures.', 'Le Journal d’Anne Frank', 'On peut également penser au Journal d’Anne Frank, dans lequel une adolescente met par écrit ses pensées, ses émotions et son quotidien alors qu’elle vit cachée pendant la Seconde Guerre mondiale. Cette référence montre que l’écriture peut aider à exprimer son vécu tout en laissant un témoignage destiné aux générations futures.', 'Feuil1', 6, 5);
