INSERT INTO literary_references (id, domain_id, source_id, title, creator, reference_text, analysis_text, source_reference, source_text, sheet_name, source_row, position) VALUES ('literature-feuil1-r07', 'references', 'references-litteraires', 'Germinal', 'Émile Zola', 'On peut également penser à Germinal d’Émile Zola, dans lequel les conditions de vie difficiles des mineurs mettent en lumière les inégalités et les injustices sociales.', 'Cette référence montre que la littérature peut rendre visibles certaines réalités et amener le lecteur à réfléchir au fonctionnement de la société.', 'Germinal – Émile Zola', 'On peut également penser à Germinal d’Émile Zola, dans lequel les conditions de vie difficiles des mineurs mettent en lumière les inégalités et les injustices sociales. Cette référence montre que la littérature peut rendre visibles certaines réalités et amener le lecteur à réfléchir au fonctionnement de la société.', 'Feuil1', 7, 6);
