INSERT INTO literary_references (id, domain_id, source_id, title, creator, reference_text, analysis_text, source_reference, source_text, sheet_name, source_row, position) VALUES ('literature-feuil1-r08', 'references', 'references-litteraires', 'Antigone', 'Sophocle', 'On peut également penser à Antigone de Sophocle, dans laquelle l’héroïne choisit de défendre ses convictions malgré l’interdiction imposée par Créon.', 'Cette référence montre que l’attachement à ses valeurs peut conduire un individu à s’opposer à l’autorité et à assumer les conséquences de ses choix.', 'Antigone – Sophocle', 'On peut également penser à Antigone de Sophocle, dans laquelle l’héroïne choisit de défendre ses convictions malgré l’interdiction imposée par Créon. Cette référence montre que l’attachement à ses valeurs peut conduire un individu à s’opposer à l’autorité et à assumer les conséquences de ses choix.', 'Feuil1', 8, 7);
