INSERT INTO literary_references (id, domain_id, source_id, title, creator, reference_text, analysis_text, source_reference, source_text, sheet_name, source_row, position) VALUES ('literature-feuil1-r09', 'references', 'references-litteraires', 'Les Fables', 'La Fontaine', 'On peut également penser aux Fables de La Fontaine, dans lesquelles les comportements humains sont représentés à travers des animaux et des situations souvent symboliques.', 'Cette référence montre que la littérature peut divertir tout en invitant le lecteur à réfléchir sur les défauts, les qualités et les rapports entre les individus.', 'Les Fables – La Fontaine', 'On peut également penser aux Fables de La Fontaine, dans lesquelles les comportements humains sont représentés à travers des animaux et des situations souvent symboliques. Cette référence montre que la littérature peut divertir tout en invitant le lecteur à réfléchir sur les défauts, les qualités et les rapports entre les individus.', 'Feuil1', 9, 8);
