INSERT INTO literary_references (id, domain_id, source_id, title, creator, reference_text, analysis_text, source_reference, source_text, sheet_name, source_row, position) VALUES ('literature-feuil1-r10', 'references', 'references-litteraires', 'Robinson Crusoé', 'Daniel Defoe', 'On peut également penser à Robinson Crusoé de Daniel Defoe, dans lequel un homme isolé sur une île doit apprendre à s’adapter à un environnement nouveau.', 'Cette référence montre que l’être humain peut développer de nouvelles ressources lorsqu’il est confronté à des difficultés ou à la solitude.', 'Robinson Crusoé – Daniel Defoe', 'On peut également penser à Robinson Crusoé de Daniel Defoe, dans lequel un homme isolé sur une île doit apprendre à s’adapter à un environnement nouveau. Cette référence montre que l’être humain peut développer de nouvelles ressources lorsqu’il est confronté à des difficultés ou à la solitude.', 'Feuil1', 10, 9);
