INSERT INTO literary_references (id, domain_id, source_id, title, creator, reference_text, analysis_text, source_reference, source_text, sheet_name, source_row, position) VALUES ('literature-feuil1-r11', 'references', 'references-litteraires', 'Harry Potter', 'J. K. Rowling', 'On peut également penser à la série Harry Potter de J. K. Rowling, dans laquelle le héros grandit en affrontant des épreuves et en construisant des relations fondées sur l’amitié et la confiance.', 'Cette référence montre que les expériences et les liens avec les autres participent à la construction de l’individu.', 'Harry Potter – J. K. Rowling', 'On peut également penser à la série Harry Potter de J. K. Rowling, dans laquelle le héros grandit en affrontant des épreuves et en construisant des relations fondées sur l’amitié et la confiance. Cette référence montre que les expériences et les liens avec les autres participent à la construction de l’individu.', 'Feuil1', 11, 10);
