INSERT INTO literary_references (id, domain_id, source_id, title, creator, reference_text, analysis_text, source_reference, source_text, sheet_name, source_row, position) VALUES ('literature-feuil1-r12', 'references', 'references-litteraires', 'El tres de mayo de 1808 en Madrid', 'Francisco de Goya', 'On peut également penser à El tres de mayo de 1808 en Madrid de Francisco de Goya : Dans la nuit du 2 au 3 mai 1808, les soldats français — en représailles à la révolte du 2 mai — exécutent les combattants espagnols faits prisonniers au cours de la bataille', NULL, 'El tres de mayo de 1808 en Madrid - Francisco de Goya', 'Dans la nuit du 2 au 3 mai 1808, les soldats français — en représailles à la révolte du 2 mai — exécutent les combattants espagnols faits prisonniers au cours de la bataille', 'Feuil1', 12, 11);
INSERT INTO literary_reference_themes (reference_id, theme, position) VALUES ('literature-feuil1-r12', 'guerre', 1);
INSERT INTO literary_references (id, domain_id, source_id, title, creator, reference_text, analysis_text, source_reference, source_text, sheet_name, source_row, position) VALUES ('literature-feuil1-r13', 'references', 'references-litteraires', 'Guernica', 'Pablo Picasso', 'On peut également penser à Guernica de Pablo Picasso : l’artiste ne représente pas de manière réaliste le bombardement de la ville espagnole, mais déforme les corps, les visages et les formes afin d’exprimer la violence et la souffrance provoquées par la guerre.', 'Cette référence montre que l’art ne se contente pas de reproduire le réel : il le transforme pour en proposer une interprétation et susciter une émotion chez le spectateur.', 'Guernica de Pablo Picasso', 'l’artiste ne représente pas de manière réaliste le bombardement de la ville espagnole, mais déforme les corps, les visages et les formes afin d’exprimer la violence et la souffrance provoquées par la guerre. Cette référence montre que l’art ne se contente pas de reproduire le réel : il le transforme pour en proposer une interprétation et susciter une émotion chez le spectateur.', 'Feuil1', 13, 12);
INSERT INTO literary_references (id, domain_id, source_id, title, creator, reference_text, analysis_text, source_reference, source_text, sheet_name, source_row, position) VALUES ('literature-feuil1-r14', 'references', 'references-litteraires', 'Nymphéas', 'Claude Monet', 'On peut également penser aux Nymphéas de Claude Monet : l’artiste ne cherche pas seulement à représenter un paysage, mais à restituer les variations de lumière, de couleur et d’atmosphère. Cette œuvre invite ainsi le spectateur à porter un regard nouveau sur une réalité pourtant ordinaire.', 'Cette référence montre que l’art peut transformer notre perception du réel en nous faisant voir autrement ce que nous pensions connaître.', 'Nymphéas de Claude Monet', 'l’artiste ne cherche pas seulement à représenter un paysage, mais à restituer les variations de lumière, de couleur et d’atmosphère. Cette œuvre invite ainsi le spectateur à porter un regard nouveau sur une réalité pourtant ordinaire. Cette référence montre que l’art peut transformer notre perception du réel en nous faisant voir autrement ce que nous pensions connaître.', 'Feuil1', 14, 13);
INSERT INTO literary_references (id, domain_id, source_id, title, creator, reference_text, analysis_text, source_reference, source_text, sheet_name, source_row, position) VALUES ('literature-feuil1-r15', 'references', 'references-litteraires', 'Comment Wang-Fô fut sauvé', 'Marguerite Yourcenar', 'On peut également penser à « Comment Wang-Fô fut sauvé » de Marguerite Yourcenar.', NULL, 'Marguerite Yourcenar, Nouvelles orientales, « Comment Wang-Fô fut sauvé », Gallimard, 1963', NULL, 'Feuil1', 15, 14);
INSERT INTO literary_references (id, domain_id, source_id, title, creator, reference_text, analysis_text, source_reference, source_text, sheet_name, source_row, position) VALUES ('literature-feuil1-r16', 'references', 'references-litteraires', 'La Passion du Christ — Évangile selon Matthieu', 'Matthieu', 'On peut également penser à la Passion du Christ, dans l’Évangile selon Matthieu, où les soldats romains humilient et tournent Jésus en dérision en le couronnant d’épines.', 'Cette référence montre que la moquerie peut devenir une forme de violence morale, destinée à rabaisser un individu et à porter atteinte à sa dignité.', 'Evangile, le Chist ', 'On peut également penser à la Passion du Christ, dans l’Évangile selon Matthieu, où les soldats romains humilient et tournent Jésus en dérision en le couronnant d’épines. Cette référence montre que la moquerie peut devenir une forme de violence morale, destinée à rabaisser un individu et à porter atteinte à sa dignité.', 'Feuil1', 16, 15);
INSERT INTO literary_references (id, domain_id, source_id, title, creator, reference_text, analysis_text, source_reference, source_text, sheet_name, source_row, position) VALUES ('literature-feuil1-r17', 'references', 'references-litteraires', 'Le Nom de la rose', 'Umberto Eco', 'On peut également penser au Nom de la rose d’Umberto Eco : le rire permet de ne plus avoir peur et de désacraliser dieu', NULL, 'umberto Eco, le nom de la rose', 'le rire permet de ne plus avoir peur et de désacraliser dieu ', 'Feuil1', 17, 16);
